package com.example.leavemanagement.balance.application;
import com.example.leavemanagement.audit.persistence.*; import com.example.leavemanagement.balance.persistence.*; import com.example.leavemanagement.policy.persistence.*; import com.example.leavemanagement.shared.api.DomainException; import com.example.leavemanagement.shared.security.CurrentActorProvider; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class BalanceAdjustmentService { private final LeaveBalanceRepository balances;private final LeaveBalanceMovementRepository movements;private final AuditEventRepository audits;private final LeaveTypeRepository types;private final CurrentActorProvider actors; public BalanceAdjustmentService(LeaveBalanceRepository b,LeaveBalanceMovementRepository m,AuditEventRepository a,LeaveTypeRepository t,CurrentActorProvider c){balances=b;movements=m;audits=a;types=t;actors=c;} private void admin(){if(!actors.require().hasRole("ADMINISTRATOR"))throw new DomainException(403,"ACCESS_DENIED","Administrator role is required");} public LeaveBalanceService.BalanceView adjust(UUID id,Command c,String idempotency){admin();var b=balances.findLockedById(id).orElseThrow(()->new DomainException(404,"RESOURCE_NOT_FOUND","Balance was not found"));if(b.getVersion()!=c.expectedVersion())throw new DomainException(409,"STALE_VERSION","The balance was changed; reload and retry");if(c.reason()==null||c.reason().isBlank()||c.adjustmentDays()==0)throw new DomainException(400,"VALIDATION_FAILED","A non-zero adjustment reason is required");if(idempotency!=null&&movements.existsByActorUserIdAndIdempotencyKey(actors.require().userId(),idempotency))throw new DomainException(409,"DUPLICATE_COMMAND","The adjustment command was already applied");int units=units(c.adjustmentDays());try{b.adjust(units);}catch(IllegalStateException ex){throw new DomainException(409,"INSUFFICIENT_BALANCE","Adjustment would make balance negative");}movements.save(LeaveBalanceMovementEntity.administration(id,units,"ADMIN_ADJUST",c.reason(),actors.require().userId(),idempotency));audits.save(AuditEventEntity.administration(actors.require().userId(),"BALANCE_ADJUSTED","LEAVE_BALANCE",id,c.reason(),null,"{\"adjustmentUnits\":"+units+"}"));return view(b);} private int units(double d){if(d*2!=Math.rint(d*2))throw new DomainException(400,"VALIDATION_FAILED","Days must be half-day units");return (int)Math.round(d*2);} private LeaveBalanceService.BalanceView view(LeaveBalanceEntity b){return new LeaveBalanceService.BalanceView(b.getId(),b.getLeaveTypeId(),types.findById(b.getLeaveTypeId()).map(LeaveTypeEntity::getName).orElse("Leave"),b.getPeriodStart(),b.getPeriodEnd(),b.getAllocatedUnits()/2.0,b.getReservedUnits()/2.0,b.getConsumedUnits()/2.0,b.getAvailableUnits()/2.0,b.getVersion());} public record Command(double adjustmentDays,String reason,long expectedVersion){} }
